import { Routes, Route, Link, useNavigate, useParams, useSearchParams, Navigate, useLocation } from 'react-router-dom';
import { Scale, Mic, Menu, Search, Heart, ShoppingCart, Bell, User, X, ChevronRight, LogOut, Plus, Minus, Trash2, ArrowRight, Package, MapPin, ShieldCheck, Store, Star, LifeBuoy, Sparkles, Upload, CheckCircle, Truck, WalletCards, QrCode, Eye, EyeOff, CalendarDays, Clock, ClipboardList, RotateCcw, Users, Settings, BarChart3, ReceiptText } from 'lucide-react';
