type UserType = { id:string; name:string; email:string; username?:string; mobile?:string; role:string };
type Product = { id:string; sku:string; name:string; slug:string; description?:string; price:number; mrp:number; stock:number; brand?:any; category?:any; images?:any[]; variants?:any[]; averageRating?:number; reviewCount?:number };

type Cart = { items:any[]; subtotal:number; count:number };

type AuthCtx = {
  user:UserType|null;
  loading:boolean;
  login:(identifier:string,password:string)=>Promise<UserType>;
  register:(payload:any)=>Promise<UserType>;
  logout:()=>void;
  refresh:()=>Promise<void>;
};
const AuthContext=createContext<AuthCtx>(null as any);
const useAuth=()=>useContext(AuthContext);

export function AuthProvider({children}:{children:any}){
  const [user,setUser]=useState<UserType|null>(null);
  const [loading,setLoading]=useState(true);
  const refresh=async()=>{
    const token=localStorage.getItem('sherise_token');
    if(!token){setUser(null);return null;}
    try{const r=await api.get('/auth/me');setUser(r.data.user);return r.data.user}
    catch(error){localStorage.removeItem('sherise_token');setUser(null);throw error}
  };
  useEffect(()=>{refresh().catch(()=>{}).finally(()=>setLoading(false))},[]);
  useEffect(()=>{const handler=()=>setUser(null);window.addEventListener('sherise-auth-expired',handler);return()=>window.removeEventListener('sherise-auth-expired',handler)},[]);
  const login=async(identifier:string,password:string)=>{
    const cleanIdentifier=identifier.trim();
    if(!cleanIdentifier || !password) throw new Error('Enter your login details');
    const r=await api.post('/auth/login',{identifier:cleanIdentifier,password});
    if(!r.data?.token || !r.data?.user) throw new Error('Login response was incomplete');
    localStorage.setItem('sherise_token',r.data.token);
    try { const me=await api.get('/auth/me'); setUser(me.data.user); return me.data.user; }
    catch(error){localStorage.removeItem('sherise_token');setUser(null);throw error}
  };
  const register=async(payload:any)=>{
    const r=await api.post('/auth/register',payload);
    if(!r.data?.token || !r.data?.user) throw new Error('Registration response was incomplete');
    localStorage.setItem('sherise_token',r.data.token);
    try { const me=await api.get('/auth/me'); setUser(me.data.user); return me.data.user; }
    catch(error){localStorage.removeItem('sherise_token');setUser(null);throw error}
  };
  const logout=()=>{localStorage.removeItem('sherise_token');setUser(null)};
  return <AuthContext.Provider value={{user,loading,login,register,logout,refresh}}>{children}</AuthContext.Provider>
}

function useToast(){const [toast,setToast]=useState('');const show=(m:string)=>{setToast(m);setTimeout(()=>setToast(''),2800)};return {toast,show}}

async function fileToDataUrl(file:File,maxSize=1400,quality=.78):Promise<string>{
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onerror=()=>reject(new Error('Could not read file'));
    reader.onload=()=>{
      const img=new Image();
      img.onload=()=>{
        const scale=Math.min(1,maxSize/Math.max(img.width,img.height));
        const canvas=document.createElement('canvas');
        canvas.width=Math.max(1,Math.round(img.width*scale));
        canvas.height=Math.max(1,Math.round(img.height*scale));
        const ctx=canvas.getContext('2d');
        if(!ctx)return reject(new Error('Image processing unavailable'));
        ctx.drawImage(img,0,0,canvas.width,canvas.height);
        resolve(canvas.toDataURL('image/jpeg',quality));
      };
      img.onerror=()=>reject(new Error('Invalid image'));
      img.src=String(reader.result);
    };
    reader.readAsDataURL(file);
  });
}

